.image-annotation { display: flex; width: 100%; flex-direction: column; align-items: center; gap: 16px; padding: 24px; color: #f5f5f5; background: #101113; border: 1px solid #ffffff14; border-radius: 18px; font-family: ui-sans-serif, system-ui, sans-serif; outline: none; }
.image-annotation *, .image-annotation *::before, .image-annotation *::after { box-sizing: border-box; }
.image-annotation__toolbar { display: flex; max-width: 100%; flex-wrap: wrap; justify-content: center; align-items: center; gap: 4px; padding: 6px; border: 1px solid #ffffff1a; border-radius: 12px; background: #242424f2; box-shadow: 0 12px 30px #0005; }
.image-annotation__toolbar button { display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 34px; border: 0; border-radius: 7px; background: transparent; color: #c8c8cc; cursor: pointer; }
.image-annotation__toolbar button:hover:not(:disabled) { background: #ffffff15; color: white; }
.image-annotation__toolbar button[aria-pressed="true"] { background: #ffffff1f; color: #67e8f9; }
.image-annotation__toolbar button:disabled, .image-annotation__toolbar input:disabled { opacity: .35; cursor: not-allowed; }
.image-annotation button:focus-visible, .image-annotation input:focus-visible { outline: 2px solid #38bdf8; outline-offset: 2px; }
.image-annotation__divider { width: 1px; height: 20px; margin: 0 3px; background: #ffffff1a; }
.image-annotation__toolbar input[type="color"] { width: 27px; height: 27px; border: 0; padding: 2px; background: transparent; cursor: pointer; }
.image-annotation__width { display: flex; align-items: center; gap: 7px; padding: 0 6px; color: #aaa; font-size: 11px; }
.image-annotation__width input { width: 75px; accent-color: #22d3ee; }
.image-annotation__width output { width: 16px; font-variant-numeric: tabular-nums; }
.image-annotation__toolbar .image-annotation__save { width: auto; min-width: 65px; gap: 6px; padding: 0 13px; margin-left: 4px; background: #f5f5f5; color: #202020; font-size: 12px; font-weight: 650; }
.image-annotation__toolbar .image-annotation__save:hover:not(:disabled) { background: white; color: #202020; }
.image-annotation__image { position: relative; width: 100%; max-width: 900px; overflow: hidden; border-radius: 18px; background: black; box-shadow: 0 0 0 1px #38bdf8aa, 0 18px 48px #0005; }
.image-annotation__image > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; pointer-events: none; user-select: none; }
.image-annotation__image > canvas { position: absolute; inset: 0; }
.image-annotation__loading { position: absolute; inset: 0; display: grid; place-items: center; background: #0005; color: #fff9; font-size: 12px; z-index: 2; }
.image-annotation__hint { margin: 0; text-align: center; color: #85858c; font-size: 11px; line-height: 1.7; }
.image-annotation__error { margin: 0; color: #fda4af; font-size: 12px; }
.image-annotation__spinner { animation: image-annotation-spin 1s linear infinite; }
@keyframes image-annotation-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .image-annotation__spinner { animation: none; } }
@media (max-width: 600px) { .image-annotation { padding: 14px; } .image-annotation__divider { display: none; } }

import { useCallback, useState, type CSSProperties, type ReactNode } from "react";
import { Brush, MousePointer2, Redo2, Square, Type, Undo2, X, Trash2, RotateCcw, LoaderCircle } from "lucide-react";
import { useAnnotationController } from "./useAnnotationController";
import { composeImageWithAnnotation } from "./compose";
import "./ImageAnnotation.css";

export interface ImageAnnotationProps {
  imageUrl: string;
  imageAlt?: string;
  /** Placeholder ratio before the image loads; the natural image ratio wins. */
  aspectRatio?: number;
  onSave?: (image: Blob) => void | Promise<void>;
  onCancel?: () => void;
  onError?: (error: Error) => void;
  className?: string;
  style?: CSSProperties;
}

export default function ImageAnnotation(props: ImageAnnotationProps) {
  // A new source owns a fresh canvas, history and loading state.
  return <AnnotationWorkspace key={props.imageUrl} {...props} />;
}

function AnnotationWorkspace({ imageUrl, imageAlt = "待涂鸦图片", aspectRatio = 3 / 2, onSave, onCancel, onError, className, style }: ImageAnnotationProps) {
  const [ratio, setRatio] = useState(aspectRatio > 0 ? aspectRatio : 3 / 2);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const reportError = useCallback((failure: Error) => { setError(failure.message); onError?.(failure); }, [onError]);
  const controller = useAnnotationController({ open: loaded, sourceImageUrl: imageUrl, onError: reportError, disabled: saving });
  const busy = saving || controller.restoring;
  const save = async () => {
    if (busy || !controller.ready || !onSave) return;
    const overlay = controller.exportOverlayCanvas();
    if (!overlay) return;
    setSaving(true);
    setError(null);
    try { await onSave(await composeImageWithAnnotation(imageUrl, overlay)); }
    catch (failure) { reportError(failure instanceof Error ? failure : new Error(String(failure))); }
    finally { setSaving(false); }
  };
  const button = (label: string, icon: ReactNode, action: () => void, active?: boolean, disabled = false) => (
    <button type="button" title={label} aria-label={label} aria-pressed={active} disabled={busy || disabled} onClick={action}>{icon}</button>
  );
  return (
    <section className={`image-annotation ${className ?? ""}`} style={style} aria-label="图片涂鸦" tabIndex={0}
      onPointerDownCapture={(event) => { if (!(event.target as HTMLElement).closest("button, input, textarea")) event.currentTarget.focus({ preventScroll: true }); }}
      onKeyDown={(event) => { if (event.key === "Escape" && !controller.isEditingText() && !busy) onCancel?.(); }}>
      <div className="image-annotation__toolbar" role="toolbar" aria-label="涂鸦工具">
        {onCancel && button("退出标注", <X size={16} />, onCancel)}
        {button("选择和移动", <MousePointer2 size={16} />, () => controller.setTool("select"), controller.tool === "select", !controller.ready)}
        {button("画笔", <Brush size={16} />, () => controller.setTool("brush"), controller.tool === "brush", !controller.ready)}
        {button("矩形", <Square size={16} />, () => controller.setTool("rect"), controller.tool === "rect", !controller.ready)}
        {button("文字", <Type size={16} />, () => controller.setTool("text"), controller.tool === "text", !controller.ready)}
        <span className="image-annotation__divider" />
        <input type="color" aria-label="标注颜色" value={controller.color} disabled={busy} onChange={(event) => controller.setColor(event.target.value)} />
        <label className="image-annotation__width">粗细<input type="range" min={1} max={24} aria-label="线条粗细" value={controller.strokeWidth} disabled={busy} onChange={(event) => controller.setStrokeWidth(Number(event.target.value))} /><output>{controller.strokeWidth}</output></label>
        <span className="image-annotation__divider" />
        {button("撤销", <Undo2 size={16} />, controller.undo, undefined, !controller.canUndo)}
        {button("重做", <Redo2 size={16} />, controller.redo, undefined, !controller.canRedo)}
        {button("删除所选", <Trash2 size={16} />, controller.deleteSelected, undefined, !controller.hasAnnotations)}
        {button("清空标注", <RotateCcw size={16} />, controller.reset, undefined, !controller.hasAnnotations)}
        <button className="image-annotation__save" type="button" disabled={busy || !controller.ready || !controller.hasAnnotations || !onSave} onClick={() => void save()}>{saving ? <><LoaderCircle size={14} className="image-annotation__spinner" />保存中…</> : "保存"}</button>
      </div>
      <div className="image-annotation__image" ref={controller.containerRef} style={{ aspectRatio: ratio }}>
        <img src={imageUrl} alt={imageAlt} draggable={false} onLoad={(event) => { setRatio(event.currentTarget.naturalWidth / event.currentTarget.naturalHeight); setLoaded(true); }} onError={() => reportError(new Error("图片加载失败，请检查图片地址"))} />
        <canvas ref={controller.canvasRef} />
        {(!controller.ready || busy) && <div className="image-annotation__loading" role="status">{error ? "图片暂不可用" : saving ? "正在保存…" : controller.restoring ? "正在恢复…" : "正在准备标注工具…"}</div>}
      </div>
      {error && <p className="image-annotation__error" role="alert">{error}</p>}
      <p className="image-annotation__hint">画笔自由涂鸦 · 拖拽绘制矩形 · 点击添加文字 · 选择后移动、缩放和旋转 · ⌘ / Ctrl Z 撤销</p>
    </section>
  );
}

export async function composeImageWithAnnotation(
  sourceImageUrl: string,
  annotationCanvas: HTMLCanvasElement,
) {
  const response = await fetch(sourceImageUrl);
  if (!response.ok) {
    throw new Error("图片加载失败");
  }

  const blobUrl = URL.createObjectURL(await response.blob());
  try {
    const source = new Image();
    source.src = blobUrl;
    await source.decode();

    const output = document.createElement("canvas");
    output.width = source.naturalWidth || source.width;
    output.height = source.naturalHeight || source.height;
    const context = output.getContext("2d");
    if (!context) {
      throw new Error("标注合成失败");
    }

    context.drawImage(source, 0, 0, output.width, output.height);
    context.drawImage(
      annotationCanvas,
      0,
      0,
      annotationCanvas.width,
      annotationCanvas.height,
      0,
      0,
      output.width,
      output.height,
    );

    const result = await new Promise<Blob | null>((resolve) =>
      output.toBlob(resolve, "image/png"),
    );
    if (!result) {
      throw new Error("标注导出失败");
    }
    return result;
  } finally {
    URL.revokeObjectURL(blobUrl);
  }
}

import type React from "react";

export type AnnotationTool = "select" | "brush" | "rect" | "text";

export interface AnnotationController {
  open: boolean;
  tool: AnnotationTool;
  setTool: (tool: AnnotationTool) => void;
  color: string;
  setColor: (color: string) => void;
  strokeWidth: number;
  setStrokeWidth: (value: number) => void;
  ready: boolean;
  canUndo: boolean;
  canRedo: boolean;
  restoring: boolean;
  hasAnnotations: boolean;
  containerRef: React.RefObject<HTMLDivElement | null>;
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  undo: () => void;
  redo: () => void;
  deleteSelected: () => void;
  reset: () => void;
  isEditingText: () => boolean;
  exportOverlayCanvas: () => HTMLCanvasElement | null;
}

import type { Canvas as FabricCanvas, FabricObject } from "fabric";

export type FabricSnapshot = string;

export function buildAnnotationBrushCursor(strokeWidth: number, color: string) {
  const size = Math.max(8, Math.min(32, Math.round(strokeWidth + 6)));
  const radius = Math.max(1.5, strokeWidth / 2);
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${size}' height='${size}' viewBox='0 0 ${size} ${size}'><circle cx='${size / 2}' cy='${size / 2}' r='${radius}' fill='${color}' stroke='white' stroke-width='1'/></svg>`;
  return `url("data:image/svg+xml;utf8,${encodeURIComponent(svg).replace(/'/g, "%27")}") ${size / 2} ${size / 2}, crosshair`;
}

export function serializeAnnotationCanvas(
  canvas: FabricCanvas,
): FabricSnapshot {
  const snapshot = canvas.toJSON() as {
    objects?: Array<Record<string, unknown>>;
  };
  snapshot.objects?.forEach((object) => {
    object.selectable = true;
    object.evented = true;
  });
  return JSON.stringify(snapshot);
}

export function isFabricTextObject(object: FabricObject) {
  return object.type.toLowerCase().replace("-", "") === "itext";
}

export function getFabricSelectionObjects(
  canvas: FabricCanvas,
): FabricObject[] {
  const active = canvas.getActiveObject();
  if (!active) return [];
  if (active.type.toLowerCase() === "activeselection") {
    return (
      active as FabricObject & { getObjects: () => FabricObject[] }
    ).getObjects();
  }
  return [active];
}

export { default as ImageAnnotation } from "./ImageAnnotation";
export type { ImageAnnotationProps } from "./ImageAnnotation";
export type { AnnotationTool } from "./controller.types";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  Canvas as FabricCanvas,
  IText as FabricIText,
  Rect as FabricRect,
} from "fabric";
import type {
  AnnotationController,
  AnnotationTool,
} from "./controller.types";
import {
  buildAnnotationBrushCursor,
  getFabricSelectionObjects,
  isFabricTextObject,
  serializeAnnotationCanvas,
  type FabricSnapshot,
} from "./fabric-canvas";

interface UseAnnotationControllerOptions {
  open: boolean;
  sourceImageUrl: string;
  onError: (error: Error) => void;
  disabled?: boolean;
}

const DEFAULT_COLOR = "#ff0000";
const DEFAULT_STROKE_WIDTH = 3;
const DEFAULT_FONT_SIZE = 24;

export function useAnnotationController({
  open,
  sourceImageUrl,
  onError,
  disabled = false,
}: UseAnnotationControllerOptions): AnnotationController {
  const [tool, setTool] = useState<AnnotationTool>("brush");
  const [color, setColorState] = useState(DEFAULT_COLOR);
  const [strokeWidth, setStrokeWidthState] = useState(DEFAULT_STROKE_WIDTH);
  const [history, setHistory] = useState({ canUndo: false, canRedo: false, restoring: false });
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;
  const [ready, setReady] = useState(false);
  const [hasAnnotations, setHasAnnotations] = useState(false);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const fabricCanvasRef = useRef<FabricCanvas | null>(null);
  const fabricModuleRef = useRef<typeof import("fabric") | null>(null);
  const toolRef = useRef(tool);
  const colorRef = useRef(color);
  const strokeWidthRef = useRef(strokeWidth);
  const undoStackRef = useRef<FabricSnapshot[]>([]);
  const redoStackRef = useRef<FabricSnapshot[]>([]);
  const currentSnapshotRef = useRef<FabricSnapshot>("");
  const restoringRef = useRef(false);
  const draftRectRef = useRef<FabricRect | null>(null);
  const rectStartRef = useRef<{ x: number; y: number } | null>(null);

  toolRef.current = tool;
  colorRef.current = color;
  strokeWidthRef.current = strokeWidth;

  const commitChange = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (!canvas || restoringRef.current) return;
    const nextSnapshot = serializeAnnotationCanvas(canvas);
    if (nextSnapshot === currentSnapshotRef.current) return;
    undoStackRef.current.push(currentSnapshotRef.current);
    redoStackRef.current = [];
    currentSnapshotRef.current = nextSnapshot;
    setHistory({ canUndo: undoStackRef.current.length > 0, canRedo: false, restoring: false });
    setHasAnnotations(canvas.getObjects().length > 0);
  }, []);

  const restoreSnapshot = useCallback(async (snapshot: FabricSnapshot) => {
    const canvas = fabricCanvasRef.current;
    if (!canvas || restoringRef.current) return;
    restoringRef.current = true;
    setHistory((state) => ({ ...state, restoring: true }));
    try {
      canvas.discardActiveObject();
      await canvas.loadFromJSON(snapshot);
      const selectable = toolRef.current === "select";
      canvas.selection = selectable;
      canvas.skipTargetFind = !selectable;
      canvas.getObjects().forEach((object) => {
        object.selectable = selectable;
        object.evented = selectable;
      });
      canvas.requestRenderAll();
      currentSnapshotRef.current = snapshot;
      setHasAnnotations(canvas.getObjects().length > 0);
    } catch (error) {
      onErrorRef.current(error instanceof Error ? error : new Error(String(error)));
    } finally {
      setHistory({ canUndo: undoStackRef.current.length > 0, canRedo: redoStackRef.current.length > 0, restoring: false });
      restoringRef.current = false;
    }
  }, []);

  useEffect(() => {
    if (!open) {
      setReady(false);
      setHasAnnotations(false);
      return;
    }
    setTool("brush");
    setColorState(DEFAULT_COLOR);
    setStrokeWidthState(DEFAULT_STROKE_WIDTH);
  }, [open, sourceImageUrl]);

  useEffect(() => {
    if (!open || !canvasRef.current || !containerRef.current) return;

    let cancelled = false;
    let resizeObserver: ResizeObserver | null = null;
    let canvas: FabricCanvas | null = null;
    let canvasSize = { width: 0, height: 0 };

    void import("fabric").then((fabric) => {
      if (cancelled || !canvasRef.current || !containerRef.current) return;

      fabricModuleRef.current = fabric;
      canvas = new fabric.Canvas(canvasRef.current, {
        enableRetinaScaling: false,
        renderOnAddRemove: true,
        preserveObjectStacking: true,
        selection: false,
      });
      fabricCanvasRef.current = canvas;
      undoStackRef.current = [];
      redoStackRef.current = [];
      currentSnapshotRef.current = serializeAnnotationCanvas(canvas);

      canvas.on("before:path:created", ({ path }) => {
        path.set({
          fill: null,
          stroke: colorRef.current,
          strokeWidth: strokeWidthRef.current,
          strokeLineCap: "round",
          strokeLineJoin: "round",
          objectCaching: false,
        });
      });

      canvas.on("path:created", ({ path }) => {
        path.set({ selectable: true, evented: true });
        commitChange();
      });
      canvas.on("object:modified", commitChange);
      canvas.on("text:editing:exited", ({ target }) => {
        const text = target as FabricIText;
        if (!text.text?.trim()) {
          canvas?.remove(text);
        }
        commitChange();
      });

      canvas.on("mouse:down", ({ e }) => {
        if (!canvas) return;
        if (toolRef.current === "text") {
          const point = canvas.getScenePoint(e);
          const text = new fabric.IText("输入文字", {
            left: point.x,
            top: point.y,
            fill: colorRef.current,
            fontFamily: "sans-serif",
            fontSize: DEFAULT_FONT_SIZE,
            fontWeight: 600,
            editingBorderColor: "#38bdf8",
            borderColor: "#38bdf8",
            cornerColor: "#ffffff",
            cornerStrokeColor: "#38bdf8",
            transparentCorners: false,
          });
          canvas.add(text);
          canvas.setActiveObject(text);
          setTool("select");
          text.enterEditing();
          text.selectAll();
          canvas.requestRenderAll();
          return;
        }
        if (toolRef.current !== "rect") return;
        const point = canvas.getScenePoint(e);
        rectStartRef.current = { x: point.x, y: point.y };
        const rect = new fabric.Rect({
          left: point.x,
          top: point.y,
          originX: "left",
          originY: "top",
          width: 1,
          height: 1,
          fill: "transparent",
          stroke: colorRef.current,
          strokeWidth: strokeWidthRef.current,
          strokeUniform: true,
          selectable: false,
          evented: false,
          objectCaching: false,
        });
        draftRectRef.current = rect;
        canvas.add(rect);
      });

      canvas.on("mouse:move", ({ e }) => {
        const start = rectStartRef.current;
        const rect = draftRectRef.current;
        if (!canvas || !start || !rect) return;
        const point = canvas.getScenePoint(e);
        rect.set({
          left: Math.min(start.x, point.x),
          top: Math.min(start.y, point.y),
          width: Math.abs(point.x - start.x),
          height: Math.abs(point.y - start.y),
        });
        rect.setCoords();
        canvas.requestRenderAll();
      });

      canvas.on("mouse:up", () => {
        const rect = draftRectRef.current;
        if (!canvas || !rect) return;
        if (rect.width < 3 || rect.height < 3) {
          canvas.remove(rect);
        } else {
          rect.set({ selectable: true, evented: true });
          commitChange();
        }
        draftRectRef.current = null;
        rectStartRef.current = null;
        canvas.requestRenderAll();
      });

      const resize = () => {
        const container = containerRef.current;
        if (!container || !canvas) return;
        const width = Math.max(1, Math.round(container.clientWidth));
        const height = Math.max(1, Math.round(container.clientHeight));
        if (!canvasSize.width) canvasSize = { width, height };
        canvas.setDimensions({ width, height });
        // Keep object coordinates and history stable when the container resizes.
        canvas.setViewportTransform([width / canvasSize.width, 0, 0, height / canvasSize.height, 0, 0]);
        canvas.wrapperEl.style.position = "absolute";
        canvas.wrapperEl.style.inset = "0";
        canvas.wrapperEl.style.width = "100%";
        canvas.wrapperEl.style.height = "100%";
        canvas.requestRenderAll();
        currentSnapshotRef.current = serializeAnnotationCanvas(canvas);
      };

      resizeObserver = new ResizeObserver(resize);
      resizeObserver.observe(containerRef.current);
      resize();
      setReady(true);
    }).catch((error) => {
      if (!cancelled) onErrorRef.current(error instanceof Error ? error : new Error(String(error)));
    });

    return () => {
      cancelled = true;
      resizeObserver?.disconnect();
      setReady(false);
      draftRectRef.current = null;
      rectStartRef.current = null;
      undoStackRef.current = [];
      redoStackRef.current = [];
      if (canvas) {
        canvas.destroy();
      }
      if (fabricCanvasRef.current === canvas) {
        fabricCanvasRef.current = null;
      }
      fabricModuleRef.current = null;
    };
  }, [commitChange, open, sourceImageUrl]);

  useEffect(() => {
    const canvas = fabricCanvasRef.current;
    const fabric = fabricModuleRef.current;
    if (!open || !canvas || !fabric) return;

    const selectable = tool === "select";
    canvas.isDrawingMode = tool === "brush";
    canvas.selection = selectable;
    canvas.skipTargetFind = !selectable;
    if (!selectable) {
      canvas.discardActiveObject();
    }
    canvas.getObjects().forEach((object) => {
      object.selectable = selectable;
      object.evented = selectable;
    });
    const cursor =
      tool === "brush"
        ? buildAnnotationBrushCursor(strokeWidth, color)
        : tool === "text"
          ? "text"
          : tool === "rect"
            ? "crosshair"
            : "default";
    canvas.defaultCursor = cursor;
    canvas.freeDrawingCursor = cursor;
    canvas.hoverCursor = selectable ? "move" : cursor;
    if (tool === "brush") {
      const brush = new fabric.PencilBrush(canvas);
      brush.width = strokeWidth;
      brush.color = color;
      canvas.freeDrawingBrush = brush;
    }
    canvas.upperCanvasEl.style.cursor = cursor;
    canvas.requestRenderAll();
  }, [color, open, ready, strokeWidth, tool]);

  const setColor = useCallback(
    (nextColor: string) => {
      setColorState(nextColor);
      const canvas = fabricCanvasRef.current;
      if (!canvas) return;
      const objects = getFabricSelectionObjects(canvas);
      if (objects.length === 0) return;
      objects.forEach((object) => {
        if (isFabricTextObject(object)) {
          object.set({ fill: nextColor });
        } else {
          object.set({ stroke: nextColor });
        }
      });
      canvas.requestRenderAll();
      commitChange();
    },
    [commitChange],
  );

  const setStrokeWidth = useCallback(
    (nextWidth: number) => {
      setStrokeWidthState(nextWidth);
      const canvas = fabricCanvasRef.current;
      if (!canvas) return;
      const objects = getFabricSelectionObjects(canvas).filter(
        (object) => !isFabricTextObject(object),
      );
      if (objects.length === 0) return;
      objects.forEach((object) => object.set({ strokeWidth: nextWidth }));
      canvas.requestRenderAll();
      commitChange();
    },
    [commitChange],
  );

  const undo = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (restoringRef.current) return;
    const previous = undoStackRef.current.pop();
    if (!canvas || previous === undefined) return;
    redoStackRef.current.push(serializeAnnotationCanvas(canvas));
    void restoreSnapshot(previous);
  }, [restoreSnapshot]);

  const redo = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (restoringRef.current) return;
    const next = redoStackRef.current.pop();
    if (!canvas || next === undefined) return;
    undoStackRef.current.push(serializeAnnotationCanvas(canvas));
    void restoreSnapshot(next);
  }, [restoreSnapshot]);

  const deleteSelected = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (!canvas) return;
    const objects = getFabricSelectionObjects(canvas);
    if (objects.length === 0) return;
    canvas.remove(...objects);
    canvas.discardActiveObject();
    canvas.requestRenderAll();
    commitChange();
  }, [commitChange]);

  const reset = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (!canvas || canvas.getObjects().length === 0) return;
    canvas.clear();
    canvas.requestRenderAll();
    commitChange();
  }, [commitChange]);

  const isEditingText = useCallback(() => {
    const active = fabricCanvasRef.current?.getActiveObject();
    return Boolean(
      active &&
      isFabricTextObject(active) &&
      Boolean((active as FabricIText).isEditing),
    );
  }, []);

  useEffect(() => {
    if (!open) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (disabled || restoringRef.current) return;
      const target = event.target as HTMLElement | null;
      if (!containerRef.current?.closest(".image-annotation")?.contains(target)) return;
      if (
        isEditingText() ||
        target?.matches("input, textarea, [contenteditable='true']")
      ) {
        return;
      }
      const withMeta = event.metaKey || event.ctrlKey;
      if (withMeta && event.key.toLowerCase() === "z") {
        event.preventDefault();
        event.stopImmediatePropagation();
        if (event.shiftKey) {
          redo();
        } else {
          undo();
        }
        return;
      }
      if (
        (event.key === "Backspace" || event.key === "Delete") &&
        fabricCanvasRef.current?.getActiveObject()
      ) {
        event.preventDefault();
        event.stopImmediatePropagation();
        deleteSelected();
      }
    };
    window.addEventListener("keydown", handleKeyDown, { capture: true });
    return () =>
      window.removeEventListener("keydown", handleKeyDown, { capture: true });
  }, [deleteSelected, disabled, isEditingText, open, redo, undo]);

  const exportOverlayCanvas = useCallback(() => {
    const canvas = fabricCanvasRef.current;
    if (!canvas || canvas.getObjects().length === 0) return null;
    canvas.discardActiveObject();
    canvas.renderAll();
    return canvas.toCanvasElement(1 / canvas.getZoom());
  }, []);

  return useMemo(
    () => ({
      open,
      tool,
      setTool,
      color,
      setColor,
      strokeWidth,
      setStrokeWidth,
      ready,
      hasAnnotations,
      ...history,
      containerRef,
      canvasRef,
      undo,
      redo,
      deleteSelected,
      reset,
      isEditingText,
      exportOverlayCanvas,
    }),
    [
      color,
      history,
      deleteSelected,
      exportOverlayCanvas,
      hasAnnotations,
      isEditingText,
      open,
      ready,
      redo,
      reset,
      setColor,
      setStrokeWidth,
      strokeWidth,
      tool,
      undo,
    ],
  );
}
